source("h.R")
# title
p("title", html_title(html_parse("<svg><title>svg</title></svg><title> A\n\tB&nbsp; C </title><title>second</title>")))
p("title body", html_title(html_parse("<p>x</p><svg><title>s</title></svg><div><title>in body</title></div>")))
p("title empty", html_title(html_parse("<title></title>"))); p("title none", html_title(html_parse("<p>")))
d <- html_parse("<title>T</title><p>x"); p("title nodeset", html_title(html_elements(d, "p"))); p("title empty ns", html_title(html_elements(d, "zz"))); p("title bad", html_title("x"))
p("title frag", html_title(html_fragment("<title>F</title>")))
# meta
d <- html_parse("<meta charset=utf-8><meta NAME=Description content='a &amp; b'><meta property=og:image content=1><meta property=og:image content=2><meta http-equiv=Refresh content=5><meta><body><div><meta itemprop=x content=inbody></div><svg><meta name=svgmeta content=s></svg>")
p("meta", html_meta(d)); p("meta str", str(html_meta(html_parse("<p>")))); p("meta nodeset self", html_meta(html_elements(d, "meta")[2:3])); p("meta div", html_meta(html_elements(d, "div")))
# json-ld
J <- function(body, type = "application/ld+json", ...) html_json_ld(html_parse(sprintf("<script type='%s'>%s</script>", type, body)), ...)
p("types", sapply(c("application/ld+json", " Application/LD+JSON ; charset=utf-8", "application/ld+json2", "application/json", "", "application/ld+json;", "application/ld+json\n"), function(t) length(J("{}", t))))
p("no type attr", html_json_ld(html_parse("<script>{}</script>")))
p("parse flags", list(tr(J("{}", parse = NA)), tr(J("{}", parse = "yes")), tr(J("{}", parse = 1))))
p("empty", J("", parse = TRUE)); p("ws", J("  ", parse = TRUE)); p("none", html_json_ld(html_parse("<p>"), parse = TRUE))
p("cdata", J("//<![CDATA[\n{\"a\":1}\n//]]>", parse = TRUE)[[1]]); p("comment", J("<!--\n{\"a\":1}\n-->", parse = TRUE)[[1]]); p("slash-star", J("/*<![CDATA[*/{\"a\":1}/*]]>*/", parse = TRUE)[[1]])
p("bignum", J('{"id": 12345678901234567890, "f": 0.1234567890123456789, "i": 9007199254740993}', parse = TRUE)[[1]])
p("dup keys", J('{"a": 1, "a": 2}', parse = TRUE)[[1]]); p("empty key", J('{"": 1}', parse = TRUE)[[1]])
p("NDJSON", J('{"a":1}\n{"b":2}', parse = TRUE)[[1]])
f <- tempfile(fileext = ".json"); writeLines('{"secret": 42}', f)
p("path body", J(f, parse = TRUE)); p("path body ws", J(paste0("\n  ", f, "\n"), parse = TRUE))
p("rel path body", { owd <- setwd(dirname(f)); on.exit(setwd(owd)); J(basename(f), parse = TRUE) })
p("url-like body (no network: file://)", J(paste0("file://", f), parse = TRUE))
p("print jsonlite fn head", head(deparse(body(jsonlite:::parse_and_simplify)), 3))
# microdata
M <- function(h, base = NULL) html_microdata(html_parse(h, base_url = base))
m <- M("<div itemscope itemtype='http://t/A  http://t/B http://t/A' itemid='i d'><span itemprop='name name alt'>N</span><span itemprop=''>empty</span><a itemprop=url href='x'>l</a><img itemprop=img><meta itemprop=m><time itemprop=t datetime=2020>y</time><time itemprop=t2>plain</time><data itemprop=d value=v>dd</data><span itemprop=name> two\n lines </span><div itemprop=sub itemscope><span itemprop=name>inner</span></div><object itemprop=o data=od></object><span itemprop='names'>partial</span><span itemprop='length'>len</span></div>", "http://h/b/")
str(m)
p("props $ partial", list(m[[1]]$properties$nam, names(m[[1]]$properties)))
m <- M("<div itemscope id=a itemref='b a c b'><span itemprop=x>1</span></div><div id=b><span itemprop=y>2</span><div itemscope itemprop=z id=zz itemref=a><span itemprop=w>3</span></div></div><span id=c itemprop=cc>4</span>")
str(m)
p("itemref cycle", str(M("<div itemscope id=a itemref=b><div id=b itemprop=p itemscope itemref=a></div></div>")))
p("itemid no type", M("<div itemscope itemid='http://x/'></div>")[[1]]$id); p("itemid w type nobase", M("<div itemscope itemtype=t itemid='rel'></div>")[[1]]$id)
p("no items", M("<p>")); p("microdata nodeset", length(html_microdata(html_elements(html_parse("<div itemscope><p itemscope itemprop=q></p></div><div itemscope></div>"), "div")[2])))
p("itemref special", tr(str(M("<div itemscope itemref='a\"b \\ ]'><span itemprop=x>1</span></div><span id='a\"b' itemprop=q>Q</span>"))))
# lists
L <- function(h, sel = "ul, ol", ...) html_list(html_element(html_parse(h), sel), ...)
h <- "<ul><li>A<li> B <ul><li>B1<li>B2<ol><li>deep</ol></ul> tail<li><li>D<div><ul><li>wrapped</ul></div><p>x</p></ul>"
p("list text", L(h)); tr0 <- p("list tree", L(h, mode = "tree")); str(tr0, max.level = 4)
for (m in list("text", "tree", "te", c("tree", "text"), c("text","tree"), NA_character_, 1, NULL, "TEXT", character(0), factor("tree"))) { cat("mode", deparse(m)[1], ": "); print(tr(class(L(h, mode = m)))) }
p("ol", L("<ol start=5><li>a<li value=9>b</ol>")); p("empty ul", L("<ul></ul>")); p("empty tree", L("<ul></ul>", mode = "tree"))
p("non-li children", L("<ul>text<li>a</li><div><li>in div</li></div><p>p</p></ul>"))
p("menu", L("<menu><li>a</menu>", "menu")); p("dl", L("<dl><dt>a</dl>", "dl")); p("doc", html_list(html_parse(h))); p("two", html_list(html_elements(html_parse(h), "ul")))
p("print n", print(L(h, mode = "tree"), n = 2))
p("long item", print(L(paste0("<ul><li>", strrep("é", 100), "</ul>"), mode = "tree")))
